40: PyDoc_STRVAR(UnixFd_tp_doc,
41: "dbus.UnixFd(value: int or file object[, variant_level: int])\n"
42: "\n"
43: "A Unix Fd.\n"
44: "\n"
45: "``value`` must be the integer value of a file descriptor, or an object that\n"
46: "implements the fileno() method. Otherwise, `ValueError` will be\n"
47: "raised.\n"
48: "\n"
49: "UnixFd keeps a dup() (duplicate) of the supplied file descriptor. The\n"
50: "caller remains responsible for closing the original fd.\n"
51: "\n"
52: ":py:attr:`variant_level` must be non-negative; the default is 0.\n"
53: "\n"
54: ".. py:attribute:: variant_level\n"
55: "\n"
56: "    Indicates how many nested Variant containers this object\n"
57: "    is contained in: if a message's wire format has a variant containing a\n"
58: "    variant containing an Unix Fd, this is represented in Python by an\n"
59: "    Unix Fd with variant_level==2.\n"
60: );
61: 
62: typedef struct {
63:     PyObject_HEAD
64:     int fd;
65:     long variant_level;
66: } UnixFdObject;
67: 
68: /* Return values:
69:  * -2 - the long value is not plausible as a file descriptor
70:  * -1 - Python failed producing a long (or in Python 2 an int)
71:  *  0 - success (value might not *actually* be a fd, but it *could* be)
72:  *  1 - arg is not a long (or in Python 2 an int)
73:  *
74:  * Or to summarize:
75:  * status  < 0 - an error occurred, and a Python exception is set.
76:  * status == 0 - all is okay, output argument *fd is set.
77:  * status  > 0 - try something else
78:  */
79: static int
80: make_fd(PyObject *arg, int *fd)
81: {
82:     long fd_arg;
83: 
84:     if (PyLong_Check(arg))
85:     {
86:         /* on Python 2 this accepts either int or long */
87:         fd_arg = PyLong_AsLong(arg);
88:         if (fd_arg == -1 && PyErr_Occurred()) {
89:             return -1;
90:         }
91:     }
92:     else {
93:         return 1;
94:     }
95:     /* Check for int overflow. */
96:     if (fd_arg < 0 || fd_arg > INT_MAX) {
97:         PyErr_Format(PyExc_ValueError, "int is outside fd range");
98:         return -2;
99:     }
100:     *fd = (int)fd_arg;
101:     return 0;
102: }
103: 
104: static PyObject *
105: UnixFd_tp_new(PyTypeObject *cls, PyObject *args, PyObject *kwargs)
106: {
107:     UnixFdObject *self = NULL;
108:     PyObject *arg;
109:     int status, fd, fd_original = -1;
110: 
111:     static char *argnames[] = {"fd", "variant_level", NULL};
112:     long variant_level = 0;
113: 
114:     if (!PyArg_ParseTupleAndKeywords(args, kwargs, "O|l", argnames, &arg, &variant_level)) {
115:         return NULL;
116:     }
117: 
118:     if (variant_level < 0) {
119:         PyErr_Format(PyExc_ValueError, "variant_level cannot be less than 0");
120:         return NULL;
121:     }
122: 
123:     status = make_fd(arg, &fd_original);
124:     if (status < 0)
125:         return NULL;
126: 
127:     if (status > 0) {
128:         if (PyObject_HasAttrString(arg, "fileno")) {
129:             PyObject *fd_number = PyObject_CallMethod(arg, "fileno", NULL);
130:             if (!fd_number)
131:                 return NULL;
132:             status = make_fd(fd_number, &fd_original);
133:             Py_CLEAR(fd_number);
134:             if (status < 0)
135:                 return NULL;
136:             if (status > 0) {
137:                 PyErr_Format(PyExc_ValueError, "Argument's fileno() method "
138:                              "returned a non-int value");
139:                 return NULL;
140:             }
141:             /* fd_original is all good. */
142:         }
143:         else {
144:             PyErr_Format(PyExc_ValueError, "Argument is not int and does not "
145:                          "implement fileno() method");
146:             return NULL;
147:         }
148:     }
149:     assert(fd_original >= 0);
150:     fd = dup(fd_original);
151:     if (fd < 0) {
152:         PyErr_Format(PyExc_ValueError, "Invalid file descriptor");
153:         return NULL;
154:     }
155: 
156:     self = (UnixFdObject *) cls->tp_alloc(cls, 0);
157:     if (!self) {
158:         close(fd);
159:         return NULL;
160:     }
161: 
162:     self->fd = fd;
163:     self->variant_level = variant_level;
164: 
165:     return (PyObject *)self;
166: }
167: 
168: static void
169: UnixFd_dealloc(UnixFdObject *self)
170: {
171:     if (self->fd >= 0) {
172:         close(self->fd);
173:         self->fd = -1;
174:     }
175: }
