177: PyDoc_STRVAR(UnixFd_take__doc__,
178: "take() -> int\n"
179: "\n"
180: "This method returns the file descriptor owned by UnixFd object.\n"
181: "Note that, once this method is called, closing the file descriptor is\n"
182: "the caller's responsibility.\n"
183: "\n"
184: "This method may be called at most once; UnixFd 'forgets' the file\n"
185: "descriptor after it is taken.\n"
186: "\n"
187: ":Raises ValueError: if this method has already been called\n"
188: );
189: static PyObject *
190: UnixFd_take(UnixFdObject *self)
191: {
192:     PyObject *fdnumber;
193: 
194:     if (self->fd < 0) {
195:         PyErr_SetString(PyExc_ValueError, "File descriptor already taken");
196:         return NULL;
197:     }
198: 
199:     fdnumber = Py_BuildValue("i", self->fd);
200:     self->fd = -1;
201: 
202:     return fdnumber;
203: }
204: 
205: int
206: dbus_py_unix_fd_get_fd(PyObject *self)
207: {
208:     return ((UnixFdObject *) self)->fd;
209: }
