37: /*
38:  * DBusGMessageQueue:
39:  *
40:  * A GSource subclass for dispatching DBusConnection messages.
41:  * We need this on top of the IO handlers, because sometimes
42:  * there are messages to dispatch queued up but no IO pending.
43:  */
44: typedef struct
45: {
46:   GSource source; /**< the parent GSource */
47:   DBusConnection *connection; /**< the connection to dispatch */
48: } DBusGMessageQueue;
49: 
50: static gboolean message_queue_prepare  (GSource     *source,
51:                                         gint        *timeout);
52: static gboolean message_queue_check    (GSource     *source);
53: static gboolean message_queue_dispatch (GSource     *source,
54:                                         GSourceFunc  callback,
55:                                         gpointer     user_data);
56: 
57: static const GSourceFuncs message_queue_funcs = {
58:   message_queue_prepare,
59:   message_queue_check,
60:   message_queue_dispatch,
61:   NULL
62: };
63: 
64: static gboolean
65: message_queue_prepare (GSource *source,
66:                        gint    *timeout)
67: {
68:   DBusConnection *connection = ((DBusGMessageQueue *)source)->connection;
69: 
70:   *timeout = -1;
71: 
72:   return (dbus_connection_get_dispatch_status (connection) == DBUS_DISPATCH_DATA_REMAINS);
73: }
74: 
75: static gboolean
76: message_queue_check (G_GNUC_UNUSED GSource *source)
77: {
78:   return FALSE;
79: }
80: 
81: static gboolean
82: message_queue_dispatch (GSource                   *source,
83:                         G_GNUC_UNUSED GSourceFunc  callback,
84:                         G_GNUC_UNUSED gpointer     user_data)
85: {
86:   DBusConnection *connection = ((DBusGMessageQueue *)source)->connection;
87: 
88:   dbus_connection_ref (connection);
89: 
90:   /* Only dispatch once - we don't want to starve other GSource */
91:   dbus_connection_dispatch (connection);
92: 
93:   dbus_connection_unref (connection);
94: 
95:   return TRUE;
96: }
