193: static gboolean
194: io_handler_dispatch (G_GNUC_UNUSED GIOChannel   *source,
195:                      GIOCondition                condition,
196:                      gpointer                    data)
197: {
198:   IOHandler *handler;
199:   guint dbus_condition = 0;
200:   DBusConnection *connection;
201: 
202:   handler = data;
203: 
204:   connection = handler->cs->connection;
205: 
206:   if (connection)
207:     dbus_connection_ref (connection);
208: 
209:   if (condition & G_IO_IN)
210:     dbus_condition |= DBUS_WATCH_READABLE;
211:   if (condition & G_IO_OUT)
212:     dbus_condition |= DBUS_WATCH_WRITABLE;
213:   if (condition & G_IO_ERR)
214:     dbus_condition |= DBUS_WATCH_ERROR;
215:   if (condition & G_IO_HUP)
216:     dbus_condition |= DBUS_WATCH_HANGUP;
217: 
218:   /* Note that we don't touch the handler after this, because
219:    * dbus may have disabled the watch and thus killed the
220:    * handler.
221:    */
222:   dbus_watch_handle (handler->watch, dbus_condition);
223:   handler = NULL;
224: 
225:   if (connection)
226:     dbus_connection_unref (connection);
227: 
228:   return TRUE;
229: }
