231: /* Attach the connection setup to the given watch, removing any
232:  * previously-attached connection setup.
233:  */
234: static void
235: connection_setup_add_watch (ConnectionSetup *cs,
236:                             DBusWatch       *watch)
237: {
238:   guint flags;
239:   GIOCondition condition;
240:   GIOChannel *channel;
241:   IOHandler *handler;
242: 
243:   if (!dbus_watch_get_enabled (watch))
244:     return;
245: 
246:   flags = dbus_watch_get_flags (watch);
247: 
248:   condition = G_IO_ERR | G_IO_HUP;
249:   if (flags & DBUS_WATCH_READABLE)
250:     condition |= G_IO_IN;
251:   if (flags & DBUS_WATCH_WRITABLE)
252:     condition |= G_IO_OUT;
253: 
254:   handler = g_new0 (IOHandler, 1);
255:   handler->cs = cs;
256:   handler->watch = watch;
257: 
258:   channel = g_io_channel_unix_new (dbus_watch_get_unix_fd (watch));
259: 
260:   handler->source = g_io_create_watch (channel, condition);
261:   g_source_set_callback (handler->source,
262:                          (GSourceFunc) (void (*) (void)) io_handler_dispatch,
263:                          handler, io_handler_source_finalized);
264:   g_source_attach (handler->source, cs->context);
265: 
266:   cs->ios = g_slist_prepend (cs->ios, handler);
267: 
268:   dbus_watch_set_data (watch, handler, io_handler_watch_freed);
269:   g_io_channel_unref (channel);
270: }
